import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherQuiz({ userName, teachingSubject, teachingGrade }) {
  const [quizzes, setQuizzes] = useState([]);
  const [title, setTitle] = useState('');

  const fetchQuizzes = () => {
    axios.get('http://localhost:8081/api/quizzes').then(res => setQuizzes(res.data));
  };

  useEffect(() => { fetchQuizzes(); }, []);

  const handleCreateQuiz = (e) => {
    e.preventDefault();
    const payload = { title, grade: teachingGrade, subject: teachingSubject, teacher_name: userName };
    axios.post('http://localhost:8081/api/add-quiz', payload).then(res => {
      if (res.data.status === "Success") {
        alert("✅ New Quiz Created!");
        setTitle('');
        fetchQuizzes();
      }
    });
  };

  const handleDeleteQuiz = (id) => {
    if (window.confirm("Delete this quiz?")) {
      axios.delete(`http://localhost:8081/api/delete-quiz/${id}`).then(() => fetchQuizzes());
    }
  };

  return (
    <div style={{ animation: 'fadeIn 0.5s' }}>
      <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📝 Manage Quizzes & Exams</h2>
      <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', marginBottom: '30px' }}>
        <h4 style={{ margin: '0 0 15px 0', color: '#475569' }}>Create New MCQ Quiz Paper</h4>
        <form onSubmit={handleCreateQuiz} style={{ display: 'flex', gap: '15px' }}>
          <input type="text" placeholder="Quiz Title (e.g. Lesson 02 Evaluation)" value={title} onChange={e => setTitle(e.target.value)} required style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1' }} />
          <button type="submit" style={{ padding: '12px 25px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Create Paper</button>
        </form>
      </div>

      <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0', color: '#64748b', fontSize: '13px' }}>
              <th style={{ padding: '12px 10px' }}>Quiz Title</th><th style={{ padding: '12px 10px' }}>Subject / Grade</th><th style={{ padding: '12px 10px', textAlign: 'center' }}>Action</th>
            </tr>
          </thead>
          <tbody>
            {quizzes.map(q => (
              <tr key={q.id} style={{ borderBottom: '1px solid #f1f5f9', fontSize: '14px' }}>
                <td style={{ padding: '12px 10px', fontWeight: 'bold' }}>{q.title}</td>
                <td style={{ padding: '12px 10px', color: '#475569' }}>{q.subject_name} ({q.grade})</td>
                <td style={{ padding: '12px 10px', textAlign: 'center' }}>
                  <button onClick={() => handleDeleteQuiz(q.id)} style={{ background: 'none', border: 'none', cursor: 'pointer' }}>🗑️</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
